                               parseFloat(($scope.charityFinancialInfo.RevenueGDRevenueAllOtherSources == '' || $scope.charityFinancialInfo.RevenueGDRevenueAllOtherSources == null) ? 0 : $scope.charityFinancialInfo.RevenueGDRevenueAllOtherSources);

