        $scope.modal.IsUploadAddress = $scope.modal.IsUploadAddress;
        //$scope.modal.UploadListOfAddresses = angular.isNullorEmpty($scope.modal.UploadListOfAddresses) ? [] : $scope.modal.UploadListOfAddresses;

